with ranked as (select * from (select *, rank() over (partition by merchant, account_id order by amount desc) as dedup_rank from transactions) t where dedup_rank = 1) select txn_type, round(avg(amount), 2) as avg_amount, sum(amount) filter (where merchant = 'Starbucks') as starbucks_total_amount, count(case when merchant = 'Grab' then 1 end) as grab_count, avg(amount) as avg_amount_2, stddev_samp(amount) as amount_stddev, grouping(txn_type) as grouping_id from ranked group by rollup (txn_type)
